class Solution {
    public boolean isSameTree(TreeNode p, TreeNode q) {
        if (p == null && q == null) {
            return true;
        }
        if (p == null || q == null) {
            return false;
        }
        if (p.val != q.val) {
            return false;
        }
        return isSameTree(p.left, q.left) && isSameTree(p.right, q.right);
    }
}

import java.util.*;

class Solution {
    public boolean isSameTree(TreeNode p, TreeNode q) {
        Queue<TreeNode[]> queue = new ArrayDeque<>();
        queue.offer(new TreeNode[] {p, q});

        while (!queue.isEmpty()) {
            TreeNode[] pair = queue.poll();
            TreeNode a = pair[0];
            TreeNode b = pair[1];

            if (a == null && b == null) {
                continue;
            }
            if (a == null || b == null || a.val != b.val) {
                return false;
            }

            queue.offer(new TreeNode[] {a.left, b.left});
            queue.offer(new TreeNode[] {a.right, b.right});
        }

        return true;
    }
}

import java.util.*;

class Solution {
    public boolean isSameTree(TreeNode p, TreeNode q) {
        Deque<Pair> stack = new ArrayDeque<>();
        stack.push(new Pair(p, q));

        while (!stack.isEmpty()) {
            Pair current = stack.pop();
            if (!same(current.left, current.right)) {
                return false;
            }
            if (current.left != null) {
                stack.push(new Pair(current.left.left, current.right.left));
                stack.push(new Pair(current.left.right, current.right.right));
            }
        }

        return true;
    }

    private boolean same(TreeNode a, TreeNode b) {
        if (a == null || b == null) {
            return a == b;
        }
        return a.val == b.val;
    }

    private static class Pair {
        TreeNode left;
        TreeNode right;

        Pair(TreeNode left, TreeNode right) {
            this.left = left;
            this.right = right;
        }
    }
}

import java.util.*;

class Solution {
    public boolean isSameTree(TreeNode p, TreeNode q) {
        List<String> first = new ArrayList<>();
        List<String> second = new ArrayList<>();
        serialize(p, first);
        serialize(q, second);
        return first.equals(second);
    }

    private void serialize(TreeNode node, List<String> output) {
        if (node == null) {
            output.add("#");
            return;
        }
        output.add(Integer.toString(node.val));
        serialize(node.left, output);
        serialize(node.right, output);
    }
}
